# ============================================
# Heart Create - メッシュ生成（統合版）
#   - パネル名: Heart Create
#   - スムース / 宝石: トグル切替
#   - パラメータは「サイズ」だけ（他は追加しない）
# ============================================

from bpy.props import EnumProperty, FloatProperty


def _ensure_scene_props():
    """Sceneに必要なプロパティを追加（重複定義しない）"""
    scn = bpy.types.Scene

    if not hasattr(scn, "heart_create_type"):
        scn.heart_create_type = EnumProperty(
            name="タイプ",
            description="生成するハートの種類",
            items=[
                ('SMOOTH', "スムース", "滑らかなハート"),
                ('JEWERLY', "宝石", "宝石カット"),
            ],
            default='SMOOTH'
        )

    if not hasattr(scn, "heart_create_size"):
        scn.heart_create_size = FloatProperty(
            name="サイズ",
            description="ハートの大きさ",
            default=1.0,
            min=0.01,
            max=100.0
        )


def _clear_scene_props():
    """registerで追加したSceneプロパティを削除"""
    scn = bpy.types.Scene
    for attr in ("heart_create_type", "heart_create_size"):
        if hasattr(scn, attr):
            delattr(scn, attr)


def _build_mesh_data(heart_type: str, size: float):
    """ハートタイプに応じて頂点/面データを返す（サイズ適用済み）"""
    if heart_type == 'SMOOTH':
        verts_src = HEART_VERTICES_SMOOTH
        faces_src = HEART_FACES_SMOOTH
    else:
        verts_src = HEART_VERTICES_JEWERLY
        faces_src = HEART_FACES_JEWERLY

    verts = [(x * size, y * size, z * size) for (x, y, z) in verts_src]
    return verts, faces_src


def _apply_shading(obj: bpy.types.Object, heart_type: str):
    """見た目（スムース/フラット）を適用"""
    # Blenderのオペレーターはコンテキスト依存なので、念のためアクティブ化
    view_layer = bpy.context.view_layer
    view_layer.objects.active = obj
    obj.select_set(True)

    if heart_type == 'SMOOTH':
        # スムースシェーディング
        try:
            bpy.ops.object.shade_smooth()
        except Exception:
            # 失敗しても致命的ではないので無視
            pass

        # オートスムーズ（Blenderバージョン差異に備えてtry）
        try:
            obj.data.use_auto_smooth = True
        except Exception:
            pass
    else:
        # 宝石カットはフラット
        try:
            bpy.ops.object.shade_flat()
        except Exception:
            pass


class MESH_OT_heart_create(bpy.types.Operator):
    """選択中の設定でハートを生成"""
    bl_idname = "mesh.heart_create"
    bl_label = "Heart Create"
    bl_options = {'REGISTER', 'UNDO'}

    # Addメニューから呼ばれる場合もあるので、Operatorにも最低限保持
    heart_type: EnumProperty(
        name="タイプ",
        items=[
            ('SMOOTH', "スムース", ""),
            ('JEWERLY', "宝石", ""),
        ],
        default='SMOOTH'
    )

    size: FloatProperty(
        name="サイズ",
        default=1.0,
        min=0.01,
        max=100.0
    )

    def execute(self, context):
        verts, faces = _build_mesh_data(self.heart_type, self.size)

        mesh = bpy.data.meshes.new("HeartMesh")
        mesh.from_pydata(verts, [], faces)
        mesh.update()

        obj = bpy.data.objects.new("Heart", mesh)
        context.collection.objects.link(obj)

        # 3Dカーソル位置に配置（余計なパラメータは増やさない）
        obj.location = context.scene.cursor.location

        _apply_shading(obj, self.heart_type)
        return {'FINISHED'}

    def draw(self, context):
        """左下の「調整（Redo）」パネルに表示されるUI。

        BlenderのRedoパネルは画面左下に固定で出るため、
        ドロップダウン（プルダウン）だと選択肢が画面外に
        はみ出して見えないことがあります。

        そこで、Enumを "expand=True" でトグルボタン表示にして
        画面内に収まるようにしています。
        """
        layout = self.layout

        row = layout.row(align=True)
        row.prop(self, "heart_type", expand=True)

        layout.prop(self, "size")


class VIEW3D_PT_heart_create_panel(bpy.types.Panel):
    """Heart Create パネル（統合UI）"""
    bl_label = "Heart Create"
    bl_idname = "VIEW3D_PT_heart_create_panel"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "Heart Create"

    def draw(self, context):
        layout = self.layout
        scn = context.scene

        # スムース / 宝石 トグル
        row = layout.row(align=True)
        row.prop(scn, "heart_create_type", expand=True)

        # パラメータはサイズのみ
        layout.prop(scn, "heart_create_size")

        # 生成ボタン（Sceneの値をOperatorに渡す）
        op = layout.operator("mesh.heart_create", text="Create", icon='HEART')
        op.heart_type = scn.heart_create_type
        op.size = scn.heart_create_size


def menu_func(self, context):
    """Add > Mesh メニューに項目を追加（統合エントリ）"""
    self.layout.separator()
    self.layout.operator(
        MESH_OT_heart_create.bl_idname,
        text="Heart Create",
        icon='HEART'
    )


classes = (
    MESH_OT_heart_create,
    VIEW3D_PT_heart_create_panel,
)


def register():
    for cls in classes:
        bpy.utils.register_class(cls)

    _ensure_scene_props()

    # Addメニューに追加
    bpy.types.VIEW3D_MT_mesh_add.append(menu_func)

    # 登録メッセージ
    print("=" * 70)
    print("✅ Heart Create アドオンが登録されました")
    print(f"   ✓ スムース: 頂点 {len(HEART_VERTICES_SMOOTH)}, 面 {len(HEART_FACES_SMOOTH)}")
    print(f"   ✓ 宝石:     頂点 {len(HEART_VERTICES_JEWERLY)}, 面 {len(HEART_FACES_JEWERLY)}")
    print("   場所: 3Dビュー > Nパネル > Heart Create / または Shift+A > Mesh > Heart Create")
    print("=" * 70)


def unregister():
    # Addメニューから削除
    try:
        bpy.types.VIEW3D_MT_mesh_add.remove(menu_func)
    except Exception:
        pass

    _clear_scene_props()

    for cls in reversed(classes):
        bpy.utils.unregister_class(cls)

    print("❌ Heart Create アドオンが登録解除されました")


if __name__ == "__main__":
    register()
